import jetbrains.mps.project.Project;
import jetbrains.mps.ide.ThreadUtils;
import jetbrains.mps.editor.runtime.HeadlessEditorComponent;
import jetbrains.mps.openapi.editor.cells.EditorCell;
import jetbrains.mps.internal.collections.runtime.Sequence;
import jetbrains.mps.openapi.editor.cells.EditorCell_Collection;
import jetbrains.mps.openapi.editor.cells.EditorCell_Label;

public final class ViewModelTestUtil {
  public ViewModelTestUtil() {
  }

  /**
   * Runs the action in a command of its own on the EDT, as in the IDE: an editor collects the model events of the
   * commands that start after it was built, and updates when such a command finishes.
   */
  public static void command(final Project project, final Runnable action) {
    Exception exception = ThreadUtils.runInUIThreadAndWait(() -> project.getModelAccess().executeCommand(action));
    if (exception != null) {
      throw new RuntimeException(exception);
    }
  }

  /**
   * Returns the text of the last label of the editor, the one that shows the value.
   */
  public static String valueCellText(HeadlessEditorComponent editor) {
    String text = null;
    for (EditorCell cell : Sequence.fromIterable((EditorCell_Collection) editor.getRootCell())) {
      if (cell instanceof EditorCell_Label) {
        text = ((EditorCell_Label) cell).getText();
      }
    }
    return text;
  }

  /**
   * Returns the text of the value cell once it is the expected one, read in commands, or after about five seconds
   * the last text read. For an update that runs in a command scheduled on the EDT.
   */
  public static String waitForValueCellText(Project project, final HeadlessEditorComponent editor, String expected) {
    final String[] text = new String[1];
    for (int i = 0; i < 50; i++) {
      command(project, () -> text[0] = valueCellText(editor));
      if (expected.equals(text[0])) {
        return text[0];
      }
      try {
        Thread.sleep(100);
      } catch (InterruptedException ex) {
        return text[0];
      }
    }
    return text[0];
  }
}
